function insert(root, word) {
  let node = root
  for (const ch of word) {
    if (!node.next[ch]) node.next[ch] = { next: {}, end: false }
    node = node.next[ch]
  }
  node.end = true
}

function search(root, word) {
  let node = root
  for (const ch of word) {
    node = node.next[ch]
    if (!node) return false
  }
  return node.end
}

